namespace Documentation.Exporter.Abstractions.Models;

/// <summary>
/// Represents the result status of a documentation export operation.
/// Errors are logged directly via Microsoft.Extensions.Logging during execution and exposed in <see cref="QualityReport"/>.
/// </summary>
public sealed class ExportResult
{
    /// <summary>
    /// Gets a value indicating whether the export operation succeeded.
    /// </summary>
    public bool IsSuccess { get; private set; }

    /// <summary>
    /// Gets the number of files generated by the export operation.
    /// </summary>
    public int GeneratedFilesCount { get; init; }

    /// <summary>
    /// Gets the documentation coverage percentage (0.0 to 100.0) calculated across all exported public types and members.
    /// </summary>
    public double DocumentationCoveragePercentage { get; init; } = 100.0;

    /// <summary>
    /// Gets the optional structured documentation quality and diagnostics report produced during execution.
    /// </summary>
    public DocumentationQualityReport? QualityReport { get; init; }

    /// <summary>
    /// Gets the collection of documentation quality and link validation diagnostics captured during execution.
    /// </summary>
    public IReadOnlyList<DocumentationDiagnostic> Diagnostics => QualityReport?.Diagnostics ?? [];

    /// <summary>
    /// Creates a successful export result.
    /// </summary>
    /// <param name="generatedFilesCount">The number of files generated.</param>
    /// <param name="coveragePercentage">The documentation coverage percentage.</param>
    /// <param name="qualityReport">Optional structured quality report captured during export.</param>
    /// <returns>A successful <see cref="ExportResult"/> instance.</returns>
    public static ExportResult Success(
        int generatedFilesCount = 0,
        double coveragePercentage = 100.0,
        DocumentationQualityReport? qualityReport = null) =>
        new()
        {
            IsSuccess = true,
            GeneratedFilesCount = generatedFilesCount,
            DocumentationCoveragePercentage = coveragePercentage,
            QualityReport = qualityReport
        };

    /// <summary>
    /// Creates a failed export result.
    /// </summary>
    /// <param name="generatedFilesCount">The number of files generated prior to failure.</param>
    /// <param name="coveragePercentage">The calculated documentation coverage percentage when available.</param>
    /// <param name="qualityReport">Optional structured quality report captured prior to failure.</param>
    /// <returns>A failed <see cref="ExportResult"/> instance.</returns>
    public static ExportResult Failure(
        int generatedFilesCount = 0,
        double coveragePercentage = 0.0,
        DocumentationQualityReport? qualityReport = null) =>
        new()
        {
            IsSuccess = false,
            GeneratedFilesCount = generatedFilesCount,
            DocumentationCoveragePercentage = coveragePercentage,
            QualityReport = qualityReport
        };
}
